        concept: '땅이 움직이고 쌓이는 원리(지질학)로 푸는 토막 시체 미스터리예요. 왜 몸이 따로따로 묻혔는지(와이더닛)를 놓고 가설이 여러 번 바뀌어요. 마지막에는 아주 긴 시간을 건너온 동기가 드러나요.',
