          '<b>규칙 하나를 네 번 다르게 쓰기.</b> 악귀(人鬼)는 산 사람의 몸에 들어가고, 체액이 닿으면 다른 사람에게 옮겨 가요. 돌려보내려면 그 몸의 주인째 죽여야 해요. 같은 규칙이 장마다 다른 수수께끼(불 속의 죽음 · 되살아났다던 범인 · 사라진 여자 · 지금 누구 안에 있나)를 만들어요. 틀린 추리가 곧 무고한 사람의 죽음이 되는 판돈도 이 규칙에서 나와요.',
          '<b>책의 틀.</b> 맨 앞 ‘기록’은 쇼와 7년(1932년)부터 쇼와 60년(1985년)까지의 흉악 사건 일곱 건을 감정 없이 늘어놓은 기록문이에요. 서평가 오모리 노조미는 각각 다마노이 토막 살인, 아베 사다 사건, 쓰야마 30인 살인, 데이긴 사건, 고토부키 산원 사건, 미쓰비시 은행 인질 사건, 파라콰트 연쇄 독살 사건을 바꾼 것으로 봐요. 이 중 네 장이 사건을 다루고, 끝의 ‘전말’에서 조수는 하인에서 동료가 되지만 악귀 셋은 풀린 채로 남아요.',
          '<b>자료에 대해.</b> 작가가 이 책의 쓰는 과정을 자세히 말한 인터뷰는 찾지 못했어요. 위의 착상 경위만 작가 발언이고, 장마다의 ‘첫 아이디어에서 완성까지’는 모두 이 노트의 추론이에요. 인물 · 사건 · 해결은 일본 · 중국 독자 서평을 맞춘 정리라서, 〈야에 사다 사건〉과 〈농약 콜라 사건〉은 마지막 진범이 누구 몸에 있었는지까지는 확인하지 못했어요. 이름은 한국어판 소개에서 확인된 것(하라다 와타루, 우라노 큐, 미요코, 기지타니)을 쓰고, 나머지는 원서 읽기를 옮겼어요.'
