        setting: '2016년, 오카야마현 북부 쓰케야마시의 외딴 마을 기지타니예요.',
        world: '기지타니에는 내력이 있어요. 전국시대에 도망 온 무사를 죽인 뒤 재앙이 이어져 악귀를 쫓는 의식(추나)을 치렀고, 1938년에는 하룻밤에 주민 30명이 살해됐어요. 악귀를 부르는 의식(쇼나)도 전해져요.',
        concept: '불 속에서 아무도 도망치지 않은 화재를 풀면, 그 화재가 지옥의 악귀 일곱을 현세로 불러낸 의식이었다는 게 드러나요. 사건의 해결이 책 전체 설정의 문을 여는 장이에요.',
        plot: '미요코의 귀향길에 따라간 하라다 앞에서, 간노지 절에 모인 청년회 남녀 일곱 명이 불에 갇혀 여섯이 죽어요. 시신에는 화상 말고 외상도 묶인 흔적도 없는데 아무도 도망치지 않았어요. 우라노는 출장 중이라 하라다가 먼저 조사를 맡아요.',
        synopsis: [
          ['도입', '하라다는 여자친구 미요코와 사귄 지 3년이 됐고, 그녀의 아버지가 야쿠자 조장 마쓰야니 넨자쿠라는 것도 알아요. 부모를 잃은 고아였던 그가 열한 살 때 누명을 쓰고 경찰관에게 맞았는데, 그 누명을 벗겨 준 사람이 탐정 우라노였다는 회상이 나와요.'],
          ['화재', '미요코의 귀향길에 따라간 오카야마 북부의 외딴 마을 기지타니에서, 간노지 절에 모인 청년회 남녀 일곱 명이 불에 갇혀 여섯이 죽어요. 스즈무라 아이지 한 명만 크게 다친 채 살아남아요. 시신에는 화상 말고 외상도 묶인 흔적도 없는데 아무도 도망치지 않았어요. 경찰이 우라노에게 도움을 청하지만 그는 오사카 일에 묶여 있어서, 하라다가 먼저 조사를 시작해요.'],
          ['마을의 내력', '전국시대에 도망 온 무사를 죽인 뒤 역병과 불운이 이어져 음양사를 불러 악귀를 쫓는 의식을 치렀고, 1938년에는 하룻밤에 30명이 살해됐다는 내력이 드러나요. 누군가 악귀를 부르는 의식을 꾸민다는 소문이 돌고, 마을에서는 앞서 불 지르기와 도둑질이 세 번 있었어요. 개를 잃은 일로 청년회에 원한을 품은 늙은 사냥꾼도 의심을 받지만 알리바이가 있어요(서평 한 곳).'],
          ['하라다의 해결', '하라다는 범인으로 보이는 남자를 쫓아 추리를 내놓아요. 자연재해와 들짐승까지 끌어들인 해결이라, 단서를 이어 붙였지만 우연에 너무 기대요.'],
          ['우라노의 해결', '돌아온 우라노가 맹점을 짚어요. 한 사람의 복수가 아니라 서로 짜지 않은 여러 사람(불을 지른 사람, 불을 틈탄 도둑, 의식을 치른 사람)의 행동이 겹친 사건이었어요. 큰불로 작은 불을 덮어 알리바이를 만든 것이 핵심이에요. 진범 스즈무라는 1938년의 살인범 무카이 도키오를 떠받들어, 청년회 회원들을 악귀를 부르는 의식의 제물로 바쳤어요.'],
          ['스승의 죽음', '혼자 수사하기 겁난 하라다는 우라노가 늘 입던 방검 조끼를 빌려 갔어요. 조끼 없이 하라다를 구하러 온 우라노는 칼에 베여 하라다의 품에서 숨을 거둬요. 누가 우라노를 베었는지는 찾은 서평에서 확인하지 못했어요.'],
          ['장의 끝', '의식이 이루어져 쇼와의 흉악범 일곱이 지옥에서 풀려나요(스즈무라가 이때 죽는다는 서평과 4장에 다시 나온다는 서평이 엇갈려요). 화장을 앞둔 우라노가 눈을 뜨는데, 안에 든 것은 염라대왕의 명을 받고 돌아온 전설의 명탐정 고조 린도예요. 책 제목 ‘명탐정의 창자’가 이 무렵 대사로 처음 나와요.']
        ],
        twist: '진범은 혼자 살아남은 스즈무라였고, 청년회 회원들을 악귀를 부르는 의식의 제물로 바쳤어요. 의식이 이루어져 악귀 일곱이 풀려나고, 죽은 우라노의 몸에 전설의 탐정 고조 린도가 들어와요.',
