          '장의 끝: 의식으로 쇼와의 악귀 일곱이 풀려나고, 화장 전의 우라노가 눈을 떠요. 안에 든 것은 염라대왕의 명을 받고 지옥에서 돌아온 고조 린도예요. 책 제목도 이 장 끝에서 처음 불린다고 해요.'
