        setting: '2016년 도쿄예요. 원 사건은 1936년 아라카와구의 여관에서 일어났어요.',
        world: '악귀는 생전의 범행을 현대에서 되풀이하거나 흉내 내요. 겉모습으로는 누가 악귀인지 알 수 없어요.',
