    intro: '부제는 ‘인민교회 살인사건’이에요. 1978년 가이아나에서 900명 넘게 죽은 인민사원 집단 죽음을 이름만 바꿔 무대로 삼았어요. 2023년 제23회 본격 미스터리 대상을 받았고, 『本格ミステリ・ベスト10』 1위, 『이 미스터리가 대단해!』 2위, 주간문춘 미스터리 베스트 10 2위에 올랐어요. 출판사는 『명탐정의 창자』의 ‘자매편’이라고 불러요. 바로 이어지는 속편은 아니고, 마지막에 두 책이 한 사람으로 이어져요.',
