            ['플롯', '<b>문제: 마지막 반전 전까지 독자를 붙잡아 둘 것.</b> 해결을 세 겹으로 쌓아요. 비서 레이코의 추리가 노부히코를 범인으로 닫고, 돌아온 노부히코의 고백이 유키에가 누군가를 감쌌다는 두 번째 그림을 열고, 화자가 그의 목을 조르는 순간 막이 내려요. 앞의 두 해결은 모두 대본이었다는 게 세 번째 해결이에요.'],
            ['퇴고', '<b>완성과 그 뒤.</b> 위키백과가 옮긴 공식 가이드 대목에 따르면, 작가는 이 책을 큰 고생 없이 써냈고 “그럭저럭 자신 있는 작품”이었다고 돌아봤어요. 그러나 노벨스판은 초판 2만 부 뒤 더 찍지 못했고, 작가는 “유난히 안 팔려서 실망했다”면서도 지금도 재미있는 작품이라고 여긴대요. 장 제목의 ‘막’과 “배우가 다 모였군” 같은 복선을 언제 넣었는지, 고쳐 쓴 과정에 대한 자료는 찾지 못했어요.']
