          basis: '확인(작가 · 『東野圭吾公式ガイド 作家生活40周年ver.』 81–82쪽, 위키백과 일본어판이 옮긴 것을 읽은 2차 인용): 닫힌 공간의 살인에 끌렸다는 것, 고립 방법에 고민했고 ‘강제로 가둔다’에 이르러 감금 설정이 나왔다는 것, 큰 고생 없이 썼고 ‘그럭저럭 자신작’이었다는 것, 초판 2만 부 뒤 증쇄가 없어 실망했다는 것, 지금도 재미있는 작품으로 본다는 것. 확인(문고 해설 · 오리하라 이치, 서평이 인용한 대목만 봄): 자기가 쓰던 소설과 똑같은 트릭이라 이 책이 싫다고 했고, 쓰던 원고를 해체해 새로 플롯을 짰다는 것. 확인(독자 서평 여러 편): 인물 · 사건 · 해결 세 겹 · 연극이라는 진상 · 결말 · ‘막’으로 된 장 제목. 추론: 착상 다음의 순서, 인질극의 편의성이 연극 결말로 이어졌다는 해석, 화자를 관객으로 고른 이유, 인물마다의 ‘왜’.'
