              ['세계', '고립을 자연이 아니라 사람이 만들어요. 『매스커레이드 호텔』도 예고 암호로 경찰을 한 건물에 묶었지만, 거기서는 묶는 장치가 진짜 범인의 것이었어요. 여기서는 묶는 장치 자체가 거짓이고, 그 거짓이 결말이에요.', [['막이 내림 · 진상', '산장을 닫은 강도가 배우였다는 순간, 닫힌 공간이라는 틀 전체가 무대 세트로 바뀌어요.']]],
              ['재료', '극단 배우와 변장이 진상의 재료예요. 『매스커레이드 호텔』의 진범도 노인 역을 잘하던 극단 배우가 노부인으로 꾸민 사람이었어요. 『신참자』의 동네 사람들이 누군가를 감싸려고 작은 거짓말을 하듯, 여기서도 도모미가 약을 원래대로 돌려 두는 ‘감싸는 거짓’이 사건을 법 밖으로 밀어내요.', [['막이 내림 · 진상', '알약 통 하나가 수단이자, 감싸는 마음의 흔적이에요.']]],
              ['형식', '이야기를 하는 사람이 사건의 핵심을 숨긴 사람이에요. 『악의』에서 범인 노노구치가 수기를 써서 독자를 속였다면, 이 책의 다카유키는 1인칭으로 자기 죄를 비켜 가며 이야기해요. 다른 점은, 노노구치는 끝까지 속이는 쪽이지만 다카유키는 속이는 사람이면서 동시에 연극에 속는 관객이라는 거예요. 다중 해결도 『악의』처럼 가짜 해결을 먼저 완성해 내놓고 무너뜨리지만, 여기서는 가짜 해결을 쓴 사람이 범인이 아니라 피해자의 가족이에요.', [['셋째 날 · 레이코의 추리', '첫 번째 해결이에요. 나중에 이것도 대본이었다는 게 드러나요.'], ['넷째 날 · 돌아온 노부히코', '두 번째 해결이 화자를 움직여, 연극이 노린 행동을 끌어내요.']]],
              ['대가', '‘모든 것이 연극’은 앞의 어색함을 한 번에 설명하지만, 독자가 따라온 사건을 한꺼번에 지워요. 그래서 허무하다, 반칙 같다는 평이 꾸준히 나오고, 화자의 어색한 속마음 때문에 범인을 일찍 짐작했다는 평도 되풀이돼요(대가는 독자 다수 의견). 『악의』가 진짜 동기의 막연함으로, 『매스커레이드 호텔』이 동기의 약함으로 값을 치렀다면, 이 책은 사건의 실체를 지운 데서 값을 치러요.', [['막이 내림 · 진상', '앞의 살인 · 투신이 모두 없던 일이 되는 대목이에요.'], ['발단 · 도모미의 죽음', '진짜 사건은 이 석 달 전의 일 하나뿐이라, 산장의 긴장이 뒤늦게 가벼워 보이는 자리예요.']]],
              ['묶기', '제목의 ‘가면’이 두 겹이에요. 현관 위에 걸린 나무 가면과, 산장의 모든 사람이 쓴 배역의 가면이에요. 스물한 해 뒤 『매스커레이드 호텔』도 ‘손님은 모두 가면을 쓰고 온다’를 제목과 주제로 삼았어요. 그리고 재인이 같은 ‘산장 3부작’으로 묶은 『눈에 갇힌 외딴 산장에서』(1992)는 배우 일곱 명이 오디션 합숙에서 ‘큰 눈으로 갇힌 산장’이라는 가짜 설정을 연기하는 이야기라, 이 책의 결말 장치를 앞으로 꺼내 다시 쓴 것으로 읽혀요. 닫힌 공간 · 연극 · 가면을 몇 해에 걸쳐 바꿔 가며 시험한 셈이에요(이 노트의 해석).']
